# -*- coding: utf-8 -*-
"""MANAPRINT — POMARE · 7 boules (le jeu de RANIHEI) · maquette de Maeva (27/11/2026,
« pomare_sans7_12_A4 »). Reprise TELLE QUELLE : 12 billets / feuille A4 PAYSAGE (3 x 4),
traits de coupe en pointillés. Chaque billet : la COURONNE ORIGINALE (posée en pochoir : en
couleur, MANAPRINT la repeint, les chiffres restent noirs), « POMARE » et « H-TMH » en écriture
TE URU, RANIHEI SISTERS & SHOP, le N°, et 7 bulles agrandies sur les pointes (badge 7 BOULES retiré).
RÈGLE (inchangée, sceau Maeva 15/08) — les pointes vont PAR PAIRES, de l'extérieur vers le centre :
   1re paire (gauche + droite) 1-15 · 2e paire 16-30 · 3e paire 31-45 · pointe du milieu 76-90.
   Les deux numéros d'une paire sont différents. Crieur : 1 à 90.
Chiffres gras 22 pt, noirs. Le tout est réduit pour garder 6 mm de marge d'impression."""
import io, random
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4, landscape
from reportlab.lib import colors

try:
    from generators import canva_masque as _masque
except Exception:
    import canva_masque as _masque

PAGE_W, PAGE_H = landscape(A4)
COLS, RANGS = 3, 4
CARTES_PAGE = COLS * RANGS                # 12
CELL_W, CELL_H = 280.6299, 148.8189
NOIR = colors.black
POLICE_NUM, T_NUM = "Helvetica-Bold", 22
# centres des 7 bulles, de gauche à droite
BULLES = [(24.211, 65.057), (57.226, 91.08), (100.146, 105.607), (147.468, 126.425),
          (190.388, 109.784), (233.308, 92.707), (258.62, 64.244)]

MARGE_SURE = 6 * 72 / 25.4
ECHELLE = min((PAGE_W - 2 * MARGE_SURE) / PAGE_W, (PAGE_H - 2 * MARGE_SURE) / PAGE_H)
DECAL_X = (PAGE_W - PAGE_W * ECHELLE) / 2.0
DECAL_Y = (PAGE_H - PAGE_H * ECHELLE) / 2.0
_DEJA = set()


def _numeros(rng):
    t = None
    for _ in range(500):
        a = rng.sample(range(1, 16), 2); b = rng.sample(range(16, 31), 2); c = rng.sample(range(31, 46), 2)
        t = (a[0], b[0], c[0], rng.randint(76, 90), c[1], b[1], a[1])
        if t not in _DEJA:
            break
    _DEJA.add(t)
    return t


def _txt(c, s, x, y, police, taille, col, centre=False):
    w = c.stringWidth(s, police, taille)
    t = c.beginText(x - w / 2.0 if centre else x, y); t.setFont(police, taille)
    t.setFillColor(col); t.textOut(s)
    c.drawText(t)


def _modele(c):
    if getattr(c, "_pomare_modele", False):
        return
    import base64
    d = _DESSIN
    for k, v in (("{HB}", "Helvetica-Bold"), ("{H}", "Helvetica")):
        d = d.replace(k, c._doc.getInternalFontName(v))
    c.beginForm("POMARE_CANVA", 0, 0, CELL_W, CELL_H)
    _masque.poser(c, "POMARE_IMG", base64.b64decode(_PNG), 0, 0, CELL_W, CELL_H)
    c._code.append("q\n" + d + "\nQ")
    c.endForm()
    c._pomare_modele = True


def _billet(c, ox, oy, serie, nums, col):
    _modele(c)
    c.saveState()
    c.translate(ox, oy)
    c.doForm("POMARE_CANVA")
    _txt(c, "N° %06d" % serie, 13.20611, 5.692526, "Helvetica-Bold", 7.5, NOIR)
    for (x, y), n in zip(BULLES, nums):
        _txt(c, str(n), x, y - 7.876, POLICE_NUM, T_NUM, col, centre=True)
    c.restoreState()


def generer_pdf(nb_cartes=None, nb_tickets=None, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", page_start=1, evenement_id="", style="", motif="", **_ig):
    n_ = nb_cartes if nb_cartes is not None else nb_tickets
    n_ = max(1, int(n_ if n_ else CARTES_PAGE))
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=(PAGE_W, PAGE_H), pageCompression=1)
    c.setTitle("POMARE · 7 boules")
    rng = random.Random(int(serie_start) * 100003 + 1508)
    _DEJA.clear()
    serie = int(serie_start)
    faits = 0
    try:
        no_page = max(1, int(page_start))
    except Exception:
        no_page = 1
    while faits < n_:
        c.setFillColor(colors.Color(0.5, 0.5, 0.5)); c.setFont("Helvetica", 7)
        c.drawRightString(PAGE_W - DECAL_X, PAGE_H - DECAL_Y / 2.0 - 2.5, "page %d" % no_page)
        entete = "  ·  ".join(t for t in ((nom_evenement or "").strip(), (date_lieu or "").strip()) if t)
        if entete:
            c.setFillColor(NOIR); c.setFont("Helvetica-Bold", 7)
            c.drawCentredString(PAGE_W / 2.0, PAGE_H - DECAL_Y / 2.0 - 2.5, entete)
        c.saveState()
        c.translate(DECAL_X, DECAL_Y); c.scale(ECHELLE, ECHELLE)
        for idx in range(CARTES_PAGE):
            if faits >= n_:
                break
            ox = (idx % COLS) * CELL_W
            oy = (RANGS - 1 - idx // COLS) * CELL_H
            _billet(c, ox, oy, serie, _numeros(rng), NOIR)
            serie += 1
            faits += 1
        c.setStrokeColor(colors.Color(0.5, 0.5, 0.5)); c.setLineWidth(0.3); c.setDash(2, 2)
        for i in range(1, COLS):
            c.line(i * CELL_W, 0, i * CELL_W, RANGS * CELL_H)
        for j in range(1, RANGS):
            c.line(0, j * CELL_H, COLS * CELL_W, j * CELL_H)
        c.restoreState()
        c.showPage()
        no_page += 1
    c.save()
    buf.seek(0)
    return buf


